use crate::packet::{Context,Cover};use hec_native_ic::{fp::Fp,poly::Poly};
pub fn verify(expected:&Context,p:&Cover)->bool{let a=&p.context;let c=&expected.c;if a.c.fp.p!=c.fp.p||a.c.g!=c.g||a.c.f!=c.f||a.d!=expected.d||a.target!=expected.target||a.ell!=expected.ell||a.sm!=expected.sm{return false}let ell=match(c.fp.p,c.f.c[0]){(101,2)=>7481,(251,18)=>67931,(601,7)=>411491,_=>return false};if expected.ell!=ell||c.g!=2||c.f!=Poly::from_coeffs(&[c.f.c[0],0,0,0,0,1])||expected.sm==0||expected.sm>=ell||p.k>=ell||p.z>=c.fp.p||p.z<=1||c.fp.pow(p.z,5)!=1||p.branches.len()!=4||p.reps.len()<2||p.primitives.is_empty(){return false}if !c.is_valid(&a.d)||!c.is_valid(&a.target)||c.is_zero(&a.d){return false}for &(x,y)in &p.reps{if x>=c.fp.p||y>=c.fp.p||c.fp.mul(y,y)!=c.f.eval(x,&c.fp){return false}}if c.mul(&c.place(p.reps[0].0,p.reps[0].1),a.sm)!=a.d{return false}
let f=Fp::new(ell);let mut roots=std::collections::BTreeSet::new();let mut product=Poly::one();for(r,_)in &p.branches{if *r>=ell||!roots.insert(*r){return false}product=product.mul(&Poly::x_minus(*r,&f),&f);}if product!=Poly::from_coeffs(&[1;5]){return false}
let mut phases=std::collections::BTreeMap::new();for(j,&(x,y))in p.reps.iter().enumerate(){let mut xx=x;for e in 0..5{if phases.insert((xx,y),(j,e,false)).is_some(){return false}let ny=c.fp.neg(y);if ny!=y&&phases.insert((xx,ny),(j,e,true)).is_some(){return false}xx=c.fp.mul(xx,p.z);}}
let step=c.place(p.reps[0].0,p.reps[0].1);let maxa=p.primitives.iter().map(|x|x.a).max().unwrap();if maxa>16{return false}let mut anchors=vec![a.target];for _ in 0..maxa{anchors.push(c.add(anchors.last().unwrap(),&step));}for anchor in &anchors{if !c.is_valid(anchor){return false}}for prim in &p.primitives{if prim.a==0{if prim.t!=0||prim.points.len()!=2{return false}let mut u=Poly::one();for &(x,y)in &prim.points{if x>=c.fp.p||y>=c.fp.p||a.target.v.eval(x,&c.fp)!=y{return false}u=u.mul(&Poly::x_minus(x,&c.fp),&c.fp);}if u!=a.target.u{return false}continue}if prim.t>=c.fp.p||!crate::geometry::exact(c,&anchors[prim.a as usize],prim.t,&prim.points){return false}}
let n=p.reps.len()+1;let mut anyscalar=false;for(r,proof)in &p.branches{if proof.w.len()!=p.primitives.len()+1||proof.w.iter().any(|w|*w>=ell)||proof.k>=ell||(!proof.excluded&&proof.k!=p.k)||(proof.excluded&&proof.k!=1){return false}let mut acc=vec![0;n];acc[0]=proof.w[0];let invsm=f.inv(a.sm);let mut rhs=f.mul(proof.w[0],invsm);for(i,prim)in p.primitives.iter().enumerate(){let w=proof.w[i+1];acc[n-1]=if prim.a==0{f.sub(acc[n-1],w)}else{f.add(acc[n-1],w)};rhs=f.sub(rhs,f.mul(w,if invsm==1{prim.a}else{f.mul(prim.a,invsm)}));for xy in &prim.points{let Some(&(j,e,neg))=phases.get(xy)else{return false};let mut coefficient=f.pow(*r,e);if neg{coefficient=f.neg(coefficient)}acc[j]=f.add(acc[j],f.mul(w,coefficient));}}let mut want=vec![0;n];let want_rhs=if proof.excluded{1}else{anyscalar=true;want[n-1]=1;p.k};if acc!=want||rhs!=want_rhs{return false}}anyscalar}
